33	function parseSession(sessionId, transcriptPath) {
34	  const lines = fs.readFileSync(transcriptPath, 'utf8').split('\n').filter(Boolean);
35	  const humanMessages = [];
36	  const agentsRun = [];
37	  const skillsRead = new Set();
38	  const corrections = [];
39	  let pendingAgent = null;
40	
41	  for (const line of lines) {
42	    let e;
43	    try { e = JSON.parse(line); } catch { continue; }
44	
45	    const role = e.message?.role;
46	    const content = e.message?.content;
47	    if (!Array.isArray(content)) continue;
48	
49	    for (const block of content) {
50	      if (role === 'user' && block.type === 'text') {
51	        const text = (block.text || '').trim();
52	        if (text.length > 2) {
53	          humanMessages.push(text.slice(0, 300));
54	          const correctionPatterns = [
55	            /\bno[,.]?\s+(don'?t|remove|stop|never|avoid)/i,
56	            /\bwrong\b/i,
57	            /\bnot like that\b/i,
58	            /\bstill\b.*\bsame\b/i,
59	            /\bagain\b/i,
60	            /\bwtf\b/i,
61	            /\bplease don'?t\b/i
62	          ];
63	          const isCorrection = correctionPatterns.some(p => p.test(text));
64	          if (isCorrection) corrections.push(text.slice(0, 200));
65	        }
66	      }
67	
68	      if (role === 'user' && block.type === 'tool_result' && pendingAgent) {
69	        const parts = Array.isArray(block.content) ? block.content : [{ type: 'text', text: String(block.content || '') }];
70	        const meta = parts.find(p => p.type === 'text' && p.text?.includes('agentId:'));
71	        if (meta) {
72	          const output = parts.filter(p => p !== meta && p.type === 'text' && p.text).map(p => p.text).join('\n').trim();
73	          agentsRun.push({
74	            type: pendingAgent.type,
75	            prompt_preview: pendingAgent.prompt,
76	            output_preview: output.slice(0, 400).replace(/\s+/g, ' '),
77	          });
78	          pendingAgent = null;
79	        }
80	      }
81	
82	      if (role === 'assistant' && block.type === 'tool_use') {
83	        if (block.name === 'Agent') {
84	          const t = (block.input?.subagent_type || 'unknown').replace(/^[^:]+:/, '').toLowerCase();
85	          pendingAgent = { type: t, prompt: (block.input?.prompt || '').slice(0, 150) };
86	        }
87	        if (block.name === 'Read') {
88	          const m = (block.input?.file_path || '').match(/skills\/([^/]+)\/SKILL\.md$/i);
89	          if (m) skillsRead.add(m[1]);
90	        }
91	      }
92	    }
93	  }
94	
95	  return {
96	    id: `sess-${Date.now()}-${crypto.randomBytes(2).toString('hex')}`,
97	    ts: new Date().toISOString(),
98	    session_id: sessionId,
99	    project: path.basename(process.cwd()),
100	    human_messages: humanMessages,
101	    corrections: corrections,
102	    agents_run: agentsRun,
103	    skills_read: [...skillsRead],
104	  };
105	}
