1	'use strict';
2	const fs = require('fs');
3	const path = require('path');
4	const os = require('os');
5	const { execSync } = require('child_process');
6	
7	const BUS_FILE = path.join(os.homedir(), '.claude', 'memory-bus.json');
8	// Use a separate dir so we don't collide with Claude's native session files
9	const SESSIONS_DIR = path.join(os.homedir(), '.claude', 'memory-sessions');
10	
11	const MEMORY_PATTERNS = [
12	  /\/\.claude\/projects\/[^/]+\/memory\/[^/]+\.md$/,
13	  /\/\.claude\/nisaba\/learning\/[^/]+\.md$/,
14	];
15	
16	// Walk the process tree: Claude → sh → node(hook). Return Claude's stable PID.
17	// Hook chain: Claude(A) spawns sh(B) which execs node(C). process.ppid=B, B's ppid=A.
18	// If Claude spawns node directly (no sh), process.ppid=A already.
19	function getSessionId() {
20	  try {
21	    const parentPid = process.ppid;
22	    const grandparentLine = execSync(`ps -p ${parentPid} -o ppid=`, {
23	      encoding: 'utf8',
24	      stdio: ['pipe', 'pipe', 'ignore'],
25	    }).trim();
26	    const grandparentPid = parseInt(grandparentLine, 10);
27	
28	    if (!isNaN(grandparentPid) && grandparentPid > 1) {
29	      // Grandparent is Claude — verify it's a long-lived node/claude process
30	      const grandCmd = execSync(`ps -p ${grandparentPid} -o comm=`, {
31	        encoding: 'utf8',
32	        stdio: ['pipe', 'pipe', 'ignore'],
33	      }).trim();
34	      // Grandparent is node/claude → use it as stable session key
35	      if (/^(node|claude)/.test(grandCmd)) {
36	        return `claude_${grandparentPid}`;
37	      }
38	    }
39	    // Fallback: parent is Claude (no intermediate sh)
40	    return `claude_${parentPid}`;
41	  } catch {
42	    return `claude_${process.ppid}`;
43	  }
44	}
45	
46	function readBus() {
47	  try { return JSON.parse(fs.readFileSync(BUS_FILE, 'utf8')); }
48	  catch { return { sequence: 0, lastWrite: null, writerSession: null, files: [] }; }
49	}
50	
51	function writeBus(sessionId, files) {
52	  const bus = readBus();
53	  bus.sequence = (bus.sequence || 0) + 1;
54	  bus.lastWrite = new Date().toISOString();
55	  bus.writerSession = sessionId;
56	  bus.files = Array.isArray(files) ? files : [files];
57	  const tmp = `${BUS_FILE}.tmp`;
58	  fs.mkdirSync(path.dirname(BUS_FILE), { recursive: true });
59	  fs.writeFileSync(tmp, JSON.stringify(bus, null, 2));
60	  fs.renameSync(tmp, BUS_FILE);
61	  return bus;
62	}
63	
64	function readSession(sessionId) {
65	  try {
66	    return JSON.parse(fs.readFileSync(path.join(SESSIONS_DIR, `${sessionId}.json`), 'utf8'));
67	  } catch {
68	    // New session: initialize lastSeenSequence to 0 so it catches any existing bus writes
69	    return { sessionId, startTime: new Date().toISOString(), lastSeenSequence: 0 };
70	  }
71	}
72	
73	function writeSession(sessionId, data) {
74	  fs.mkdirSync(SESSIONS_DIR, { recursive: true });
75	  fs.writeFileSync(path.join(SESSIONS_DIR, `${sessionId}.json`), JSON.stringify(data, null, 2));
76	}
77	
78	function isMemoryFile(filePath) {
79	  return Boolean(filePath && MEMORY_PATTERNS.some(p => p.test(filePath)));
80	}
81	
82	function cleanOldSessions() {
83	  try {
84	    const cutoff = Date.now() - 24 * 3600 * 1000;
85	    for (const f of fs.readdirSync(SESSIONS_DIR)) {
86	      if (!f.endsWith('.json')) continue;
87	      const full = path.join(SESSIONS_DIR, f);
88	      if (fs.statSync(full).mtimeMs < cutoff) fs.unlinkSync(full);
89	    }
90	  } catch {}
91	}
92	
93	module.exports = { getSessionId, readBus, writeBus, readSession, writeSession, isMemoryFile, cleanOldSessions, BUS_FILE, SESSIONS_DIR };
