19	function parseFrontmatter(content) {
20	  const match = content.match(/^---\s*\n([\s\S]*?)\n---/);
21	  if (!match) return {};
22	  const out = {};
23	  for (const line of match[1].split('\n')) {
24	    const sep = line.indexOf(':');
25	    if (sep === -1) continue;
26	    const k = line.slice(0, sep).trim();
27	    const v = line.slice(sep + 1).trim().replace(/^["']|["']$/g, '');
28	    if (k) out[k] = v;
29	  }
30	  return out;
31	}
